CREATE SCHEMA gm_game;
REVOKE ALL ON SCHEMA gm_game FROM PUBLIC,anon,authenticated;
SET LOCAL search_path=gm_game,pg_catalog;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, username TEXT DEFAULT '', role TEXT NOT NULL DEFAULT 'player',created_at BIGINT NOT NULL,last_seen BIGINT NOT NULL,level BIGINT DEFAULT 1,xp BIGINT DEFAULT 0);
CREATE TABLE IF NOT EXISTS wallets(user_id TEXT PRIMARY KEY REFERENCES users(id), gm BIGINT NOT NULL DEFAULT 0 CHECK(gm>=0),cr BIGINT NOT NULL DEFAULT 0 CHECK(cr>=0),vault BIGINT NOT NULL DEFAULT 0 CHECK(vault>=0));
CREATE TABLE IF NOT EXISTS pools(name TEXT PRIMARY KEY, gm BIGINT NOT NULL DEFAULT 0 CHECK(gm>=0),cr BIGINT NOT NULL DEFAULT 0 CHECK(cr>=0));
CREATE TABLE IF NOT EXISTS journal(id TEXT PRIMARY KEY,at BIGINT NOT NULL,actor TEXT NOT NULL,kind TEXT NOT NULL,info TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tickets(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),category TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',priority TEXT NOT NULL DEFAULT 'P3',assigned_to TEXT,claimed_at BIGINT,first_reply_at BIGINT,auto_attempts BIGINT NOT NULL DEFAULT 0,resolved_at BIGINT,updated_at BIGINT NOT NULL,created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS used_admin_2fa(owner_id TEXT NOT NULL,step BIGINT NOT NULL,PRIMARY KEY(owner_id,step));
 CREATE TABLE IF NOT EXISTS admin_2fa_failures(owner_id TEXT NOT NULL,at BIGINT NOT NULL);
 CREATE INDEX IF NOT EXISTS idx_admin_2fa_failures ON admin_2fa_failures(owner_id,at);
CREATE TABLE IF NOT EXISTS holding_buckets(name TEXT PRIMARY KEY, gm BIGINT NOT NULL DEFAULT 0 CHECK(gm>=0));
CREATE TABLE IF NOT EXISTS restrictions(user_id TEXT PRIMARY KEY REFERENCES users(id),end_at BIGINT,reason TEXT,issued_by TEXT NOT NULL,issued_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS ticket_messages(id TEXT PRIMARY KEY,ticket_id TEXT NOT NULL REFERENCES tickets(id),author TEXT NOT NULL,body TEXT NOT NULL,created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_tickets_status ON tickets(status,priority,created_at);
CREATE TABLE IF NOT EXISTS game_settings(k TEXT PRIMARY KEY,v TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS mining_state(user_id TEXT PRIMARY KEY REFERENCES users(id),last_at BIGINT NOT NULL,reg_micro BIGINT NOT NULL DEFAULT 0,overflow_micro BIGINT NOT NULL DEFAULT 0,processed_cents BIGINT NOT NULL DEFAULT 0,pending_cents BIGINT NOT NULL DEFAULT 0,last_xp_day TEXT NOT NULL DEFAULT '');
 CREATE TABLE IF NOT EXISTS mining_upgrades(user_id TEXT PRIMARY KEY REFERENCES users(id),level BIGINT NOT NULL DEFAULT 1 CHECK(level BETWEEN 1 AND 200),updated_at BIGINT NOT NULL DEFAULT 0);
 CREATE TABLE IF NOT EXISTS early_player_awards(slot BIGINT PRIMARY KEY CHECK(slot BETWEEN 1 AND 20),user_id TEXT NOT NULL UNIQUE REFERENCES users(id),awarded_at BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS holding_state(user_id TEXT PRIMARY KEY REFERENCES users(id),pending_cents BIGINT NOT NULL DEFAULT 0,last_withdraw_day TEXT NOT NULL DEFAULT '',carry_micro BIGINT NOT NULL DEFAULT 0,partial_micro BIGINT NOT NULL DEFAULT 0,last_checkpoint BIGINT NOT NULL DEFAULT 0);
 CREATE TABLE IF NOT EXISTS holding_peak(user_id TEXT PRIMARY KEY REFERENCES users(id),peak_cents BIGINT NOT NULL DEFAULT 0);
 CREATE TABLE IF NOT EXISTS points_account(user_id TEXT PRIMARY KEY REFERENCES users(id),points BIGINT NOT NULL DEFAULT 0,day TEXT NOT NULL DEFAULT '',daily_volume_cents BIGINT NOT NULL DEFAULT 0,daily_points BIGINT NOT NULL DEFAULT 0);
 CREATE TABLE IF NOT EXISTS referrals(user_id TEXT PRIMARY KEY REFERENCES users(id),referrer_id TEXT NOT NULL REFERENCES users(id),created_at BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),side TEXT NOT NULL CHECK(side IN ('buy','sell')),limit_price BIGINT NOT NULL,amount_cents BIGINT NOT NULL,remaining_cents BIGINT NOT NULL,locked_cents BIGINT NOT NULL,fee_paid_cents BIGINT NOT NULL DEFAULT 0,gross_received_cents BIGINT NOT NULL DEFAULT 0,quote_remainder BIGINT NOT NULL DEFAULT 0,status TEXT NOT NULL,auction BIGINT NOT NULL DEFAULT 0,created_at BIGINT NOT NULL,priority BIGINT NOT NULL,expires_at BIGINT,duration_sec BIGINT NOT NULL DEFAULT 0);
 CREATE INDEX IF NOT EXISTS idx_orders_book ON orders(side,status,limit_price,priority);
 CREATE TABLE IF NOT EXISTS trades(rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT PRIMARY KEY,buy_order TEXT NOT NULL,sell_order TEXT NOT NULL,buyer TEXT NOT NULL,seller TEXT NOT NULL,price BIGINT NOT NULL,amount_cents BIGINT NOT NULL,quote_cents BIGINT NOT NULL,at BIGINT NOT NULL,auction BIGINT NOT NULL DEFAULT 0,suspect BIGINT NOT NULL DEFAULT 0);
 CREATE TABLE IF NOT EXISTS points_pair_day(day TEXT NOT NULL,user_id TEXT NOT NULL,other_id TEXT NOT NULL,eligible_gm_cents BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(day,user_id,other_id));
 CREATE TABLE IF NOT EXISTS box_day(day TEXT NOT NULL,user_id TEXT NOT NULL,gm_cents BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(day,user_id));
 CREATE TABLE IF NOT EXISTS box_collection(user_id TEXT PRIMARY KEY REFERENCES users(id),
  bronze BIGINT NOT NULL DEFAULT 0 CHECK(bronze>=0),
  silver BIGINT NOT NULL DEFAULT 0 CHECK(silver>=0),
  gold BIGINT NOT NULL DEFAULT 0 CHECK(gold>=0));
 CREATE TABLE IF NOT EXISTS request_ids(id TEXT PRIMARY KEY,actor TEXT NOT NULL,kind TEXT NOT NULL,created_at BIGINT NOT NULL,response TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS order_activity(user_id TEXT NOT NULL,at BIGINT NOT NULL);
 CREATE INDEX IF NOT EXISTS idx_order_activity ON order_activity(user_id,at);
 CREATE INDEX IF NOT EXISTS idx_order_activity_time ON order_activity(at);
 CREATE TABLE IF NOT EXISTS shop_day(user_id TEXT NOT NULL,day TEXT NOT NULL,cr_cents BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(user_id,day));
 CREATE TABLE IF NOT EXISTS daily_claim(user_id TEXT NOT NULL,day TEXT NOT NULL,PRIMARY KEY(user_id,day));
 CREATE TABLE IF NOT EXISTS tasks_claim(user_id TEXT NOT NULL,task_id TEXT NOT NULL,PRIMARY KEY(user_id,task_id));
 CREATE TABLE IF NOT EXISTS achievements(user_id TEXT NOT NULL,code TEXT NOT NULL,PRIMARY KEY(user_id,code));
 CREATE TABLE IF NOT EXISTS balance_ledger(id TEXT NOT NULL,account TEXT NOT NULL,currency TEXT NOT NULL,delta_cents BIGINT NOT NULL,created_at BIGINT NOT NULL,PRIMARY KEY(id,account,currency));
CREATE TABLE IF NOT EXISTS holder_nonces (nonce TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS holder_wallets (user_id TEXT PRIMARY KEY REFERENCES users(id),wallet_address TEXT NOT NULL UNIQUE,verified_at BIGINT NOT NULL,public_opt_in BIGINT NOT NULL DEFAULT 0 CHECK(public_opt_in IN (0,1)));
CREATE TABLE IF NOT EXISTS holder_snapshots (user_id TEXT PRIMARY KEY REFERENCES users(id),master_address TEXT NOT NULL,amount_raw TEXT NOT NULL,decimals BIGINT NOT NULL,checked_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_holder_snapshots_checked ON holder_snapshots(checked_at);
